python3 - <<'EOF'
import csv, re

lines = open('/app/dataset/genealogy_trees.txt', encoding='utf-8').read().split('\n')
grid = lines[5:110]

people = {}
with open('/app/dataset/people_accounts.csv', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        people[f"{row['first_name']} {row['last_name']}"] = int(row['account_balance'])

frag_re = re.compile(r"[^\W\d_]+(?: [^\W\d_]+)*", re.UNICODE)
frags = []
for r, line in enumerate(grid):
    for m in frag_re.finditer(line):
        frags.append([r, m.start(), m.end(), m.group()])

used = [False]*len(frags)
boxes = []  # (name, row, colstart, colend)

def overlap(a, b):
    return min(a[2], b[2]) - max(a[1], b[1]) > 0

# 1) two-row combos (vertical wrap): fragA on row r, fragB on row r+1, overlapping cols
by_row = {}
for i, f in enumerate(frags):
    by_row.setdefault(f[0], []).append(i)

matched = {}
for i, f in enumerate(frags):
    if used[i]: continue
    # try single-fragment full-name match
    if f[3] in people:
        # but could also be part of a wrap; prefer wrap if combo matches? check both
        pass

# do combos first (wrapped names), then singles
for i, f in enumerate(frags):
    if used[i]: continue
    for j in by_row.get(f[0]+1, []):
        g = frags[j]
        if used[j] or not overlap(f, g): continue
        combo = f"{f[3]} {g[3]}"
        if combo in people and combo not in matched:
            # avoid stealing: only if neither fragment alone is a full name that's still unplaced... keep simple, check later
            matched[combo] = (f[0], min(f[1],g[1]), max(f[2],g[2]))
            used[i] = used[j] = True
            break

for i, f in enumerate(frags):
    if used[i]: continue
    if f[3] in people and f[3] not in matched:
        matched[f[3]] = (f[0], f[1], f[2])
        used[i] = True

print("matched boxes:", len(matched))
un = [frags[i] for i in range(len(frags)) if not used[i]]
print("unmatched fragments:", len(un))
for f in un: print("  ", f)
EOF

