import csv, re, sys
from collections import defaultdict

LINES = open('/app/dataset/genealogy_trees.txt', encoding='utf-8').read().split('\n')
GRID = [l for l in LINES[5:110]]
H = len(GRID)
def at(r, c):
    if 0 <= r < H and 0 <= c < len(GRID[r]):
        return GRID[r][c]
    return ' '

WIRE = set('|│/\\+_')       # vertical-ish connector chars
RAIL = set('-~+')           # horizontal connector chars
BORDER = RAIL | WIRE

people = {}
with open('/app/dataset/people_accounts.csv', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        people[f"{row['first_name']} {row['last_name']}"] = int(row['account_balance'])

# ---- locate name fragments ----
frag_re = re.compile(r"[^\W\d_]+(?: [^\W\d_]+)*", re.UNICODE)
frags = []
for r, line in enumerate(GRID):
    for m in frag_re.finditer(line):
        frags.append([r, m.start(), m.end(), m.group()])
by_row = defaultdict(list)
for i, f in enumerate(frags):
    by_row[f[0]].append(i)
used = [False]*len(frags)
def overlap(a, b): return min(a[2], b[2]) - max(a[1], b[1]) > 0

boxes = {}  # name -> dict
for i, f in enumerate(frags):
    if used[i]: continue
    for j in by_row.get(f[0]+1, []):
        g = frags[j]
        if used[j] or not overlap(f, g): continue
        combo = f"{f[3]} {g[3]}"
        if combo in people and combo not in boxes:
            boxes[combo] = dict(trows=(f[0], g[0]), c0=min(f[1], g[1]), c1=max(f[2], g[2]))
            used[i] = used[j] = True
            break
for i, f in enumerate(frags):
    if used[i]: continue
    if f[3] in people and f[3] not in boxes:
        boxes[f[3]] = dict(trows=(f[0], f[0]), c0=f[1], c1=f[2])
        used[i] = True

assert len(boxes) > 0
leftover = [frags[i] for i in range(len(frags)) if not used[i]]

# ---- determine box rectangles ----
def is_border_row(r, c0, c1):
    cnt = sum(1 for c in range(c0, c1) if at(r, c) in RAIL)
    return cnt >= 2

for name, b in boxes.items():
    r0, r1 = b['trows']; c0, c1 = b['c0'], b['c1']
    # top border: nearest row above text rows that has horizontal border chars
    top = None
    for r in range(r0-1, r0-4, -1):
        if is_border_row(r, c0-3, c1+3):
            top = r; break
    bot = None
    for r in range(r1+1, r1+4):
        if is_border_row(r, c0-3, c1+3):
            bot = r; break
    if top is None: top = r0-1
    if bot is None: bot = r1+1
    # left/right edges from border rows and side chars
    lefts, rights = [], []
    for r in (top, bot):
        cs = [c for c in range(max(0,c0-6), c1+6) if at(r, c) in RAIL]
        if cs: lefts.append(min(cs)); rights.append(max(cs))
    for r in range(top+1, bot):
        # side border chars
        for c in range(max(0,c0-4), c0):
            if at(r, c) in ('|','│','+'): lefts.append(c)
        for c in range(c1, c1+4):
            if at(r, c) in ('|','│','+'): rights.append(c)
    b['top'], b['bot'] = top, bot
    b['left'] = min(lefts) if lefts else c0-2
    b['right'] = max(rights) if rights else c1+1

# occupancy map for hit-testing (expanded by 1)
occ = {}
for name, b in boxes.items():
    for r in range(b['top'], b['bot']+1):
        for c in range(b['left']-1, b['right']+2):
            occ[(r, c)] = name

def box_hit(r, c):
    return occ.get((r, c))

# ---- tracing ----
def is_rail_at(r, c):
    """is (r,c) on a horizontal rail (not a box border)?"""
    if box_hit(r, c): return False
    cnt = 0
    for dc in range(-6, 7):
        if at(r, c+dc) in RAIL and not box_hit(r, c+dc):
            cnt += 1
    return cnt >= 4 and at(r, c) in RAIL | {' '}

def trace_down(r, c, maxgap=2):
    """trace a jagged vertical downward from just below (r,c).
    returns ('box', name) or ('rail', row, col) or ('dead', row, col)"""
    gap = 0
    r0 = r
    while r < H + 2:
        r += 1
        hit = box_hit(r, c) or box_hit(r, c-1) or box_hit(r, c+1)
        if hit:
            return ('box', box_hit(r, c) or box_hit(r, c-1) or box_hit(r, c+1))
        # rail?
        if at(r, c) == '+' and not box_hit(r, c):
            # plus could be rail junction; check horizontal neighbors
            if is_rail_at(r, c):
                return ('rail', r, c)
        if is_rail_at(r, c) and at(r, c) in RAIL:
            return ('rail', r, c)
        # continue vertical
        best = None
        for dc in (0, -1, 1, -2, 2):
            ch = at(r, c+dc)
            if ch in WIRE:
                best = c+dc; break
        if best is None:
            # tolerate gap: also treat rail chars '-','~' as possible degraded vertical? no.
            gap += 1
            if gap > maxgap:
                return ('dead', r, c)
        else:
            gap = 0
            ch = at(r, best)
            c = best
            if ch == '/': c -= 1
            elif ch == '\\': c += 1
    return ('dead', r, c)

def expand_rail(r, c, maxgap=4):
    """walk rail row left/right from (r,c); return (cmin, cmax)"""
    cmin = cmax = c
    # left
    gap = 0; cc = c
    while cc > 0:
        cc -= 1
        if box_hit(r, cc): break
        if at(r, cc) in RAIL:
            cmin = cc; gap = 0
        else:
            gap += 1
            if gap > maxgap: break
    gap = 0; cc = c
    while cc < 7000:
        cc += 1
        if box_hit(r, cc): break
        if at(r, cc) in RAIL:
            cmax = cc; gap = 0
        else:
            gap += 1
            if gap > maxgap: break
    return cmin, cmax

def find_drops(r, cmin, cmax, skipcol):
    """find downward wires below rail row r in [cmin,cmax], excluding near skipcol (parent attach)"""
    cols = []
    for c in range(cmin, cmax+1):
        if at(r+1, c) in WIRE:
            cols.append(c)
    # group adjacent
    groups = []
    for c in cols:
        if groups and c - groups[-1][-1] <= 1:
            groups[-1].append(c)
        else:
            groups.append([c])
    return [g[len(g)//2] for g in groups]

# ---- build tree ----
children = defaultdict(list)
parent_of = {}
issues = []
for name, b in boxes.items():
    # find stem start below bottom border
    starts = [c for c in range(b['left'], b['right']+1) if at(b['bot']+1, c) in WIRE]
    if not starts:
        continue  # leaf
    # group adjacent, take groups
    groups = []
    for c in starts:
        if groups and c - groups[-1][-1] <= 1: groups[-1].append(c)
        else: groups.append([c])
    if len(groups) > 1:
        issues.append((name, 'multi-stem', groups))
    c = groups[0][len(groups[0])//2]
    res = trace_down(b['bot'], c)
    if res[0] == 'box':
        kid = res[1]
        children[name].append(kid)
        parent_of.setdefault(kid, name)
    elif res[0] == 'rail':
        rr, rc = res[1], res[2]
        cmin, cmax = expand_rail(rr, rc)
        drops = find_drops(rr, cmin, cmax, rc)
        if not drops:
            issues.append((name, 'rail-no-drops', rr, cmin, cmax))
        for dc in drops:
            res2 = trace_down(rr, dc)
            if res2[0] == 'box':
                kid = res2[1]
                if kid == name:
                    continue
                children[name].append(kid)
                if kid in parent_of and parent_of[kid] != name:
                    issues.append((kid, 'two-parents', parent_of[kid], name))
                parent_of.setdefault(kid, name)
            else:
                issues.append((name, 'drop-dead', dc, res2))
    else:
        issues.append((name, 'stem-dead', res))

roots = [n for n in boxes if n not in parent_of]
print("boxes:", len(boxes))
print("roots:", roots)
print("edges:", sum(len(v) for v in children.values()))
print("issues:", len(issues))
for it in issues[:40]: print("  ", it)

# connectivity check
seen = set()
stack = [r for r in roots]
while stack:
    n = stack.pop()
    if n in seen: continue
    seen.add(n)
    stack.extend(children.get(n, []))
print("reachable from roots:", len(seen), "of", len(boxes))

import json
with open('/tmp/tree.json', 'w') as f:
    json.dump({'children': dict(children), 'parent': parent_of, 'roots': roots}, f, ensure_ascii=False)
EOF
