only_down = down_edges - up_edges
only_up = up_edges - down_edges
print("edges both:", len(both), "only-down:", len(only_down), "only-up:", len(only_up))

# combine: trust 'both' first, then fill children lacking a parent
parent_of = {}
conflicts = defaultdict(set)
for p, k in both: conflicts[k].add(p)
for p, k in only_down | only_up: conflicts[k].add(p)
multi = {k: v for k, v in conflicts.items() if len(v) > 1}
print("children with conflicting parents:", len(multi))
for k, v in multi.items(): print("  ", k, "<-", v)

for p, k in both: parent_of[k] = p
for p, k in only_down | only_up:
    if k not in parent_of: parent_of[k] = p

roots = [n for n in boxes if n not in parent_of]
print("roots:", len(roots), roots[:10])
children = defaultdict(list)
for k, p in parent_of.items(): children[p].append(k)
seen = set(); stack = list(roots)
while stack:
    n = stack.pop()
    if n in seen: continue
    seen.add(n); stack.extend(children[n])
print("reachable:", len(seen), "of", len(boxes))
print("notes:", len(notes))
for n in notes[:30]: print("  ", n)

import json
with open('/tmp/tree.json', 'w') as f:
    json.dump({'parent': parent_of, 'roots': roots}, f, ensure_ascii=False)
